css:
.tpl-hf-carousel-spotlight { position: relative; width: 100%; height: 100%; overflow: hidden; display: flex; align-items: center; justify-content: center; background: radial-gradient(ellipse 95% 55% at 50% -10%, rgba(110,110,180,0.16) 0%, transparent 65%), var(--bg, #0a0a0f); font-family: var(--font-sans, 'Inter', 'PingFang SC', sans-serif); color: var(--fg, #ffffff); perspective: 1200px; }
.tpl-hf-carousel-spotlight .page-card { width: 88%; height: 84%; max-width: 1580px; border-radius: 22px; background: linear-gradient(180deg, rgba(22,22,32,0.96), rgba(11,11,17,0.98)); border: 1px solid rgba(255,255,255,0.12); box-shadow: -26px 26px 60px rgba(0,0,0,0.45), 0 0 80px rgba(0,0,0,0.25); padding: clamp(20px, 3.6vmin, 44px) clamp(24px, 4vmin, 52px) clamp(28px, 4.6vmin, 56px); display: flex; flex-direction: column; justify-content: space-between; transform-style: preserve-3d; opacity: 0; overflow: visible; }
.tpl-hf-carousel-spotlight .sp-nav { display: flex; align-items: center; justify-content: space-between; font-size: clamp(13px, 1.5vmin, 18px); color: var(--muted, #a1a1aa); opacity: 0; }
.tpl-hf-carousel-spotlight .sp-hero { text-align: center; margin: clamp(6px, 1.5vh, 18px) 0; opacity: 0; }
.tpl-hf-carousel-spotlight .sp-title { font-size: clamp(24px, 4.4vmin, 56px); font-weight: 800; line-height: 1.18; }
.tpl-hf-carousel-spotlight .sp-hl { color: var(--accent, #edcb50); border-bottom: 3px solid var(--accent, #edcb50); padding-bottom: 2px; text-shadow: 0 0 26px rgba(237,203,80,0.35); }
.tpl-hf-carousel-spotlight .sp-bar { margin: clamp(10px, 2vh, 20px) auto 0; max-width: 560px; display: flex; align-items: center; justify-content: space-between; padding: 6px 6px 6px 18px; border-radius: 999px; background: #1a1a22; border: 1px solid rgba(255,255,255,0.12); font-size: clamp(12px, 1.4vmin, 16px); color: #94a3b8; }
.tpl-hf-carousel-spotlight .sp-cta { padding: 0.55em 1.3em; border-radius: 999px; background: linear-gradient(135deg, var(--accent, #edcb50), #f59e0b); color: #09090b; font-weight: 800; }
.tpl-hf-carousel-spotlight .sp-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: clamp(12px, 2.2vw, 32px); perspective: 900px; transform-style: preserve-3d; margin-top: clamp(10px, 1.8vh, 20px); }
.tpl-hf-carousel-spotlight .sp-item { min-height: clamp(120px, 24vh, 240px); border-radius: 16px; border: 1px solid rgba(255,255,255,0.12); background: linear-gradient(145deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02)); padding: clamp(16px, 2.4vmin, 28px); display: flex; flex-direction: column; justify-content: flex-end; font-size: clamp(16px, 2.4vmin, 28px); font-weight: 700; opacity: 0; line-height: 1.3; }
.tpl-hf-carousel-spotlight .sp-item.is-focus { border-color: var(--accent, #edcb50); background: linear-gradient(145deg, rgba(237,203,80,0.18), rgba(24,24,34,0.92)); box-shadow: 0 24px 50px rgba(0,0,0,0.55), 0 0 40px rgba(237,203,80,0.22); }
